# -*- coding: utf-8 -*-
"""
基金季报 4.4.1 章节专用高频结构化套话正则模式
作用：利用传统NLP正则表达式，精准拦截无实际业务支撑的宏观叙事和套路句式
"""
import re

NONSENSE_PATTERNS = [
    # 模式 1：描述宏观大盘走势的车轱辘话
    re.compile(r"(回顾.*?季度|报告期内|本季度).*?(呈现|表现出|面临).*?(震荡|分化|压力|走势|态势|行情)"),
    
    # 模式 2：空洞的基金投资理念宣示
    re.compile(r"本基金.*?(始终|继续|依然|坚持).*?(理念|原则|初衷|底线)"),
    
    # 模式 3：毫无信息量的表态与跟风描述
    re.compile(r"(密切关注|紧紧围绕|积极寻找|审慎评估).*?(行业动态|宏观政策|结构性机会|潜在风险)"),
    
    # 模式 4：AI生成感极强的免责/套路结语
    re.compile(r"(力争|期望|努力)为(持有人|投资者)(创造|带来)(稳定|长期|稳健)的回报")
]
